from pathlib import Path

def rep(path, old, new, count=1):
    p=Path(path); s=p.read_text()
    if old not in s:
        raise SystemExit(f'PATTERN NOT FOUND in {path}: {old[:120]!r}')
    s=s.replace(old,new,count)
    p.write_text(s)

