rep(p,"<button class=\"dcc-ca-tab ${tab==='summary'?'active':''}\" onclick=\"dccClientAdmin('${id}','summary')\">Resumen</button><button class=\"dcc-ca-tab ${tab==='food'?'active':''}\" onclick=\"dccClientAdmin('${id}','food')\">Alimentación</button><button class=\"dcc-ca-tab ${tab==='training'?'active':''}\" onclick=\"dccClientAdmin('${id}','training')\">Entrenamiento</button><button class=\"dcc-ca-tab ${tab==='progress'?'active':''}\" onclick=\"dccClientAdmin('${id}','progress')\">Progreso</button>",
"<button class=\"dcc-ca-tab ${tab==='summary'?'active':''}\" onclick=\"dccClientAdmin('${id}','summary')\">Resumen</button><button class=\"dcc-ca-tab ${tab==='food'?'active':''}\" onclick=\"dccClientAdmin('${id}','food')\">Dieta</button><button class=\"dcc-ca-tab ${tab==='training'?'active':''}\" onclick=\"dccClientAdmin('${id}','training')\">Rutina</button><button class=\"dcc-ca-tab ${tab==='progress'?'active':''}\" onclick=\"dccClientAdmin('${id}','progress')\">Progreso</button><button class=\"dcc-ca-tab ${tab==='followup'?'active':''}\" onclick=\"dccClientAdmin('${id}','followup')\">Seguimiento</button>")
anchor="function render(id,tab='summary'){"
follow="""function monthlyPhotoText(id){const x=data?.checkins?.[id]||{},raw=x.sentAt??x.sent_at??x.created_at??null;if(!raw)return'Pendiente · 3 fotos';const d=new Date(raw);if(!Number.isFinite(d.getTime()))return'Pendiente · 3 fotos';const next=new Date(d);next.setMonth(next.getMonth()+1);return next<=new Date()?'Pendiente · 3 fotos':`Próximo · ${next.toLocaleDateString('es-ES',{day:'numeric',month:'short'})}`}
function followupPane(id){const x=data?.checkins?.[id]||{},has=!!(x.sentAt||x.sent_at||x.created_at||x.updated_at);return `<section class=\"dcc-ca-card\"><div class=\"dcc-ca-title\"><h2>Seguimiento</h2><span style=\"font-size:9px;color:#8f98a3\">Todo en un solo lugar</span></div><div style=\"display:grid;gap:8px;margin-top:12px\"><button class=\"dcc-ca-detail\" style=\"width:100%;min-height:52px;text-align:left;padding:10px 13px\" onclick=\"${has?`window.__dccCheckinReturnClient='${id}';reviewCheckin('${id}')`:`toast('Todavía no hay un check-in enviado')`}\"><b style=\"display:block;font-size:12px\">Check-in semanal</b><span style=\"display:block;margin-top:4px;font-size:9px;opacity:.72\">${has?esc(lastCheckin(id)):'Sin check-in enviado'}</span></button><div style=\"padding:12px 13px;border:1px solid rgba(217,170,74,.32);border-radius:14px\"><b style=\"font-size:12px\">Check-in fotográfico mensual</b><div style=\"margin-top:5px;color:#8f98a3;font-size:9px\">3 fotos: espalda · frente · lateral</div><div style=\"margin-top:7px;color:${G2};font-size:10px;font-weight:800\">${esc(monthlyPhotoText(id))}</div></div><button class=\"dcc-ca-detail\" style=\"width:100%;min-height:52px;text-align:left;padding:10px 13px\" onclick=\"dccOpenClientChat('${id}')\"><b style=\"display:block;font-size:12px\">Mensajes</b><span style=\"display:block;margin-top:4px;font-size:9px;opacity:.72\">Abrir conversación con el cliente →</span></button></div></section>`}
window.dccOpenClientChat=function(id){window.__dccChatReturnClient=String(id);if(typeof window.dccOpenChat==='function')window.dccOpenChat(id)};
"""
