old="function pane(id,t,cl,m){if(t==='food')return foodPane(id);if(t==='training')return trainingPane(id);if(t==='progress')return`<section class=\"dcc-ca-card\"><div class=\"dcc-ca-title\"><h2>Progreso</h2></div><div class=\"dcc-ca-grid\">${info('Peso inicial',m.initial.toFixed(1).replace('.',',')+' kg')}${info('Peso actual',m.current.toFixed(1).replace('.',',')+' kg')}${info('Grasa inicial',m.fi!=null?m.fi.toFixed(1).replace('.',',')+' %':'—')}${info('Grasa actual',m.fc!=null?m.fc.toFixed(1).replace('.',',')+' %':'—')}</div></section>`;const ss=workouts30(id);return`<section class=\"dcc-ca-card\"><div class=\"dcc-ca-title\"><h2>Información general</h2></div><div class=\"dcc-ca-grid\">${info('Objetivo',esc(cl.goal||'—'))}${info('Edad',clientAge(cl))}${info('Altura',clientHeight(cl))}${info('Último check-in',lastCheckin(id))}${info('Alimentos a evitar',esc(avoidText(cl)||'Sin alimentos indicados'))}</div></section><section class=\"dcc-ca-card\"><div class=\"dcc-ca-activity-head\"><h2>Actividad de entrenamiento</h2><button class=\"dcc-ca-detail\" onclick=\"dccClientAdmin('${id}','training')\">Ver entrenamiento →</button></div><div class=\"dcc-ca-activity\"><div class=\"dcc-ca-activity-item\"><small>Últimos 30 días</small><b>${ss.length} sesiones</b></div><div class=\"dcc-ca-activity-item\"><small>Última sesión</small><b>${lastWorkout(id)}</b></div></div></section><button class=\"dcc-ca-delete\" onclick=\"dccLegacyDelete('${id}')\">Eliminar cliente</button>`}"
new="function pane(id,t,cl,m){if(t==='food')return foodPane(id);if(t==='training')return trainingPane(id);if(t==='progress')return`<section class=\"dcc-ca-card\"><div class=\"dcc-ca-title\"><h2>Progreso</h2></div><div class=\"dcc-ca-grid\">${info('Peso inicial',m.initial.toFixed(1).replace('.',',')+' kg')}${info('Peso actual',m.current.toFixed(1).replace('.',',')+' kg')}${info('Grasa inicial',m.fi!=null?m.fi.toFixed(1).replace('.',',')+' %':'—')}${info('Grasa actual',m.fc!=null?m.fc.toFixed(1).replace('.',',')+' %':'—')}</div></section>`;if(t==='followup')return followupPane(id);return`<section class=\"dcc-ca-card\"><div class=\"dcc-ca-title\"><h2>Información general</h2></div><div class=\"dcc-ca-grid\">${info('Objetivo',esc(cl.goal||'—'))}${info('Edad',clientAge(cl))}${info('Altura',clientHeight(cl))}${info('Último check-in',lastCheckin(id))}${info('Alimentos a evitar',esc(avoidText(cl)||'Sin alimentos indicados'))}</div></section>`}"
